CREATE OR REPLACE TRIGGER HOTEL_GESTAO.TRG_RESERVA_BIU_QUARTO
BEFORE INSERT OR UPDATE OF COD_QUARTO
ON HOTEL_GESTAO.TB_RESERVA
FOR EACH ROW

DECLARE
    V_SITUACAO HOTEL_GESTAO.TB_QUARTO.DSC_SITUACAO%TYPE;
BEGIN

    SELECT DSC_SITUACAO
      INTO V_SITUACAO
      FROM HOTEL_GESTAO.TB_QUARTO
     WHERE COD_QUARTO = :NEW.COD_QUARTO;

    IF V_SITUACAO <> 'DISPONIVEL' THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            'O quarto selecionado nao esta disponivel para reserva.'
        );
    END IF;

END;
/

